// Geometry + manifest tests for the final 1920x960 vector office world.
//
// The shipped `lib/office-map.json` is now GENERATED by
// `scripts/build-approved-office-map.ts` from the approved review artifacts
// (see docs/reviews/approved-map-selection.json). These tests pin the final
// approved topology, the exact furnished inventory, the derived semantics
// (open Tele top, open Wastafel path, sealed toilets/Gudang/Server, wall-mounted
// Best Agent board) and a grid BFS with the real 18x12 actor footprint.
//
// The pure geometry primitives, collision model, lookups, hotspot proximity and
// camera clamping keep the same contract as before.

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  BILIK_GENG_ZONE_ID,
  DEFAULT_HOTSPOT_RANGE,
  MapValidationError,
  actorFootBox,
  clampCamera,
  intersectRect,
  isBlocked,
  isWalkable,
  nearestHotspot,
  officeMap,
  rectArea,
  rectContainsPoint,
  rectContainsRect,
  seatFor,
  validateManifest,
  zoneAt,
  type FurnitureKind,
  type HotspotKind,
  type OfficeManifest,
  type Point,
  type Rect,
} from '../lib/office-map.ts';

const clone = (): OfficeManifest => structuredClone(officeMap);

// Transform anchors from the approved source pixels (see the generator).
const worldX = (x: number): number => Math.round((60 + (x - 44) * 1.25) * 100) / 100;
const worldY = (y: number): number => Math.round((40 + (y - 41) * 1.25) * 100) / 100;

// ---------------------------------------------------------------------------
// Manifest shape + validation
// ---------------------------------------------------------------------------

void test('manifest declares a 1920x960 world with six seats inside Bilik Geng Kami', () => {
  assert.equal(officeMap.width, 1920);
  assert.equal(officeMap.height, 960);
  assert.ok(officeMap.margin > 0 && officeMap.margin < 100);
  assert.ok(officeMap.actor.halfWidth > 0 && officeMap.actor.feet > 0);
  assert.equal(officeMap.seats.length, 6);

  const geng = officeMap.zones.find((zone) => zone.id === BILIK_GENG_ZONE_ID);
  assert.ok(geng, 'a Bilik Geng Kami zone exists');
  assert.equal(geng?.name, 'Bilik Geng Kami');

  for (const seat of officeMap.seats) {
    assert.equal(seat.zone, BILIK_GENG_ZONE_ID, `${seat.id} is assigned to Bilik Geng Kami`);
    assert.ok(rectContainsPoint(geng!.rect, seat.x, seat.y), `${seat.id} sits inside the room rect`);
  }
  assert.deepEqual(
    officeMap.seats.map((seat) => seat.cid),
    [1, 2, 3, 4, 5, 6],
  );
});

void test('the shipped manifest passes strict validation', () => {
  assert.doesNotThrow(() => validateManifest(officeMap));
});

void test('all geometry ids are unique across every collection', () => {
  const ids: string[] = [];
  for (const group of [
    officeMap.seats,
    officeMap.zones,
    officeMap.walls,
    officeMap.columns,
    officeMap.blocks,
    officeMap.furniture,
    officeMap.openings,
    officeMap.windows,
    officeMap.hotspots,
  ]) {
    for (const entry of group) ids.push(entry.id);
  }
  assert.equal(new Set(ids).size, ids.length, 'duplicate geometry id');
});

void test('every zone, collider and hotspot lies inside the world', () => {
  const inside = (rect: Rect): boolean => rect.x >= 0 && rect.y >= 0 && rect.x + rect.w <= officeMap.width && rect.y + rect.h <= officeMap.height;
  for (const group of [officeMap.zones, officeMap.walls, officeMap.columns, officeMap.blocks, officeMap.furniture, officeMap.hotspots, officeMap.openings, officeMap.windows]) {
    for (const entry of group) assert.ok(inside(entry.rect), `${entry.id} is inside the world`);
  }
});

void test('every furniture, seat, hotspot and surface references a real zone', () => {
  const zoneIds = new Set(officeMap.zones.map((zone) => zone.id));
  for (const item of officeMap.furniture) assert.ok(zoneIds.has(item.zone), `furniture ${item.id} references ${item.zone}`);
  for (const seat of officeMap.seats) assert.ok(zoneIds.has(seat.zone), `seat ${seat.id} references ${seat.zone}`);
  for (const hotspot of officeMap.hotspots) assert.ok(zoneIds.has(hotspot.zone), `hotspot ${hotspot.id} references ${hotspot.zone}`);
  for (const surface of officeMap.surfaces) assert.ok(zoneIds.has(surface.zone), `surface references ${surface.zone}`);
});

void test('seat cids are unique', () => {
  const cids = officeMap.seats.map((seat) => seat.cid);
  assert.equal(new Set(cids).size, cids.length);
});

void test('validation rejects a duplicate id with a clear error', () => {
  const bad = clone();
  bad.zones.push({ ...bad.zones[0]! });
  assert.throws(() => validateManifest(bad), (error: unknown) => error instanceof MapValidationError && /duplicate/i.test(error.message));
});

void test('validation rejects geometry outside the world', () => {
  const bad = clone();
  bad.zones.push({ id: 'over-the-edge', name: 'Over', kind: 'open', rect: { x: 1900, y: 100, w: 200, h: 200 } });
  assert.throws(() => validateManifest(bad), (error: unknown) => error instanceof MapValidationError && /world|bounds/i.test(error.message));
});

void test('validation rejects a non-positive rectangle', () => {
  const bad = clone();
  bad.walls.push({ id: 'flat-wall', kind: 'full', rect: { x: 100, y: 100, w: 0, h: 40 } });
  assert.throws(() => validateManifest(bad), MapValidationError);
});

void test('validation rejects a seat that is not inside Bilik Geng Kami', () => {
  const bad = clone();
  bad.seats[0]!.x = 600;
  bad.seats[0]!.y = 600;
  assert.throws(() => validateManifest(bad), (error: unknown) => error instanceof MapValidationError && /Bilik Geng Kami/.test(error.message));
});

void test('validation rejects a seat that is not walkable', () => {
  const bad = clone();
  const desk = bad.furniture.find((entry) => entry.solid && entry.zone === BILIK_GENG_ZONE_ID)!;
  bad.seats[0]!.x = desk.rect.x + desk.rect.w / 2;
  bad.seats[0]!.y = desk.rect.y + desk.rect.h / 2;
  assert.throws(() => validateManifest(bad), (error: unknown) => error instanceof MapValidationError && /walkable/i.test(error.message));
});

void test('validation rejects an unknown zone reference and a bad actor', () => {
  const badSurface = clone();
  badSurface.surfaces.push({ zone: 'nowhere', kind: 'office' });
  assert.throws(() => validateManifest(badSurface), (error: unknown) => error instanceof MapValidationError && /zone/i.test(error.message));

  const badActor = clone();
  badActor.actor.halfWidth = 0;
  assert.throws(() => validateManifest(badActor), MapValidationError);
});

