void test('there is no forbidden Koridor Servis / Koridor Bawah zone, label or collider', () => {
  const offenders = [
    ...officeMap.zones.map((zone) => `${zone.id} ${zone.name}`),
    ...officeMap.blocks.map((block) => `${block.id} ${block.name}`),
    ...officeMap.openings.map((opening) => opening.id),
    ...officeMap.furniture.map((item) => item.id),
  ].filter((text) => /koridor\s+(servis|bawah)/i.test(text));
  assert.deepEqual(offenders, []);
});

void test('the main circulation is lorong-utama and the open strip is jalur-terbuka', () => {
  const lorong = officeMap.zones.find((zone) => zone.id === 'lorong-utama');
  assert.ok(lorong, 'lorong-utama exists');
  assert.equal(lorong?.kind, 'corridor');

  const jalur = officeMap.zones.find((zone) => zone.id === 'jalur-terbuka');
  assert.ok(jalur, 'jalur-terbuka exists');
  assert.equal(jalur?.kind, 'corridor');
  assert.ok(jalur!.rect.y <= worldY(244) + 0.01, 'the strip starts at the main circulation');
  assert.ok(jalur!.rect.y + jalur!.rect.h <= worldY(476) + 0.01, 'the strip stops at the Wastafel wall');
});

void test('unlabelled transit/tiny zones keep their name for zoneAt but are not painted', () => {
  for (const id of ['sirkulasi', 'jalur-terbuka', 'wastafel']) {
    const zone = officeMap.zones.find((entry) => entry.id === id);
    assert.ok(zone, `${id} exists for semantics`);
    assert.ok(zone!.name.length > 0, `${id} keeps its name`);
    assert.equal(zone!.showLabel, false, `${id} is not painted`);
    const cx = zone!.rect.x + zone!.rect.w / 2;
    const cy = zone!.rect.y + zone!.rect.h / 2;
    assert.equal(zoneAt(officeMap, cx, cy)?.id, id, `${id} still resolves through zoneAt`);
  }
  for (const id of ['meeting-1', 'hrga', 'komisaris', 'product-manager', 'it', 'direktur-finance', 'bilik-geng-kami', 'resepsionis', 'lobby-besar', 'pantry', 'gudang', 'toilet-wanita', 'toilet-pria', 'meeting-2', 'server', 'desk-collection', 'tele-cs-ca', 'lorong-utama']) {
    const zone = officeMap.zones.find((entry) => entry.id === id)!;
    assert.notEqual(zone.showLabel, false, `${id} keeps its room label`);
  }
});

void test('there are exactly three structural columns', () => {
  assert.equal(officeMap.columns.length, 3);
  assert.deepEqual(officeMap.columns.map((column) => column.id).sort(), ['col-geng-1', 'col-komisaris', 'col-meeting-1']);
});

void test('Desk Collection and Tele stop at the service block and do not extend downward', () => {
  for (const id of ['desk-collection', 'tele-cs-ca']) {
    const zone = officeMap.zones.find((entry) => entry.id === id)!;
    assert.equal(zone.rect.y + zone.rect.h, worldY(501), `${id} ends at source y=501`);
  }
  const below = [...officeMap.walls, ...officeMap.furniture].filter((entry) => entry.rect.y > worldY(501) + 2 && entry.rect.x + entry.rect.w > worldX(695));
  assert.deepEqual(below.map((entry) => entry.id), []);
});

void test('the six assigned seats map to the six approved Bilik Geng Kami chairs', () => {
  for (let i = 1; i <= 6; i += 1) {
    const chair = officeMap.furniture.find((item) => item.id === `F-GENG-C${i}`);
    const seat = officeMap.seats.find((entry) => entry.cid === i)!;
    assert.ok(chair, `approved chair F-GENG-C${i} exists`);
    assert.equal(seat.x, Math.round((chair!.rect.x + chair!.rect.w / 2) * 100) / 100);
    assert.equal(seat.y, Math.round((chair!.rect.y + chair!.rect.h / 2) * 100) / 100);
  }
  assert.deepEqual(
    officeMap.seats.map((seat) => `${seat.cid}:${seat.direction}`),
    ['1:down', '2:down', '3:up', '4:up', '5:right', '6:left'],
  );
});

