const EXPECTED_INVENTORY: Record<string, Partial<Record<FurnitureKind, number>>> = {
  'meeting-1': { table: 1, chair: 6 },
  hrga: { desk: 2, chair: 4, cabinet: 1, dispenser: 1 },
  komisaris: { desk: 1, chair: 1 },
  'product-manager': { desk: 1, chair: 1 },
  it: { desk: 2, chair: 2 },
  'direktur-finance': { desk: 2, counter: 1, chair: 2 },
  'bilik-geng-kami': { desk: 2, chair: 6, cabinet: 1 },
  resepsionis: { counter: 1, chair: 1, sofa: 4 },
  'lorong-utama': { dispenser: 2 },
  pantry: { counter: 1, dispenser: 1, fridge: 1, chair: 1 },
  'meeting-2': { table: 2, chair: 6 },
  sirkulasi: { table: 2, chair: 2 },
  'desk-collection': { desk: 2, chair: 34, board: 1 },
  'tele-cs-ca': { desk: 2, chair: 24 },
};

void test('furniture matches the exact approved count per room', () => {
  const actual = new Map<string, Map<FurnitureKind, number>>();
  for (const item of officeMap.furniture) {
    const inner = actual.get(item.zone) ?? new Map<FurnitureKind, number>();
    inner.set(item.kind, (inner.get(item.kind) ?? 0) + 1);
    actual.set(item.zone, inner);
  }
  const sortEntries = (entries: Array<[string, number]>): Array<[string, number]> => [...entries].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  for (const [zone, expected] of Object.entries(EXPECTED_INVENTORY)) {
    const got = actual.get(zone) ?? new Map<FurnitureKind, number>();
    assert.deepEqual(Object.fromEntries(sortEntries([...got.entries()])), Object.fromEntries(sortEntries(Object.entries(expected))), `inventory for ${zone}`);
  }
  for (const zone of ['gudang', 'toilet-wanita', 'toilet-pria', 'wastafel', 'server']) {
    assert.equal(officeMap.furniture.filter((item) => item.zone === zone).length, 0, `no invented furniture in ${zone}`);
  }
});

void test('Desk Collection and Tele carry the approved banks and visible chairs', () => {
  assert.equal(officeMap.furniture.filter((item) => item.zone === 'desk-collection' && item.kind === 'chair').length, 34);
  assert.equal(officeMap.furniture.filter((item) => item.zone === 'tele-cs-ca' && item.kind === 'chair').length, 24);
  assert.equal(officeMap.furniture.filter((item) => item.id === 'F-DC-BANK-TOP' || item.id === 'F-DC-BANK-BOTTOM').length, 2);
  assert.equal(officeMap.furniture.filter((item) => item.id === 'F-TC-BANK-L' || item.id === 'F-TC-BANK-R').length, 2);
});

void test('chairs/sofas/board are decorative and hard furniture is solid', () => {
  for (const item of officeMap.furniture) {
    if (item.kind === 'chair' || item.kind === 'sofa' || item.kind === 'board') {
      assert.equal(item.solid, false, `${item.id} (${item.kind}) must be non-solid`);
    } else {
      assert.equal(item.solid, true, `${item.id} (${item.kind}) must be solid`);
    }
  }
});

