void test('the Tele / CS / CA top edge is open to the main circulation', () => {
  const seamY = worldY(244);
  const separatorX = worldX(1156);
  for (const wall of officeMap.walls) {
    const horizontal = wall.rect.w > wall.rect.h;
    if (horizontal && wall.rect.y <= seamY && wall.rect.y + wall.rect.h >= seamY && wall.rect.x + wall.rect.w > separatorX + 1e-6) {
      assert.fail(`wall ${wall.id} crosses the open Tele top`);
    }
  }
  for (const x of [worldX(1180), worldX(1300), worldX(1440)]) {
    assert.equal(isWalkable(officeMap, x, worldY(270)), true, `Tele top open at source x=${x}`);
  }
});

void test('the Wastafel north path is open all the way to the main circulation', () => {
  const x = worldX(537);
  for (let y = worldY(232); y <= worldY(472); y += 20) {
    assert.equal(isWalkable(officeMap, x, y), true, `wash path open at world y=${y}`);
  }
});

void test('Gudang, both toilets and the Server are sealed, but their door approaches are walkable', () => {
  const sealed: Array<[string, Point]> = [
    ['gudang', { x: 551.25, y: 545 }],
    ['toilet-wanita', { x: 617.5, y: 566 }],
    ['toilet-pria', { x: 720.5, y: 560 }],
    ['server', { x: 808.75, y: 540 }],
  ];
  for (const [id, point] of sealed) {
    assert.equal(isWalkable(officeMap, point.x, point.y), false, `${id} interior is sealed`);
    assert.ok(officeMap.blocks.some((block) => block.kind === 'sealed' && rectContainsPoint(block.rect, point.x, point.y)), `${id} has a sealed block`);
  }
  assert.equal(isWalkable(officeMap, 551.25, worldY(384)), true, 'Gudang door approach (corridor side)');
  assert.equal(isWalkable(officeMap, 655, worldY(440)), true, 'Toilet Wanita door approach (strip side)');
  assert.equal(isWalkable(officeMap, 687, worldY(430)), true, 'Toilet Pria door approach (strip side)');
  assert.equal(isWalkable(officeMap, 890, 550), true, 'Server door approach (Desk Collection side)');
});

void test('the Best Agent Performance board is a slim, wall-mounted, non-solid board with a hotspot', () => {
  const board = officeMap.furniture.find((item) => item.id === 'F-WA-BOARD-BAP');
  assert.ok(board, 'the board exists');
  assert.equal(board?.kind, 'board');
  assert.equal(board?.solid, false, 'the board is wall-mounted, so non-solid');
  assert.equal(board?.zone, 'desk-collection');
  assert.ok(board!.rect.w <= 10, 'the board is slim (<= 10 world px deep)');

  const wall = officeMap.walls.find((entry) => entry.id === 'w-m2-east')!;
  assert.ok(board!.rect.x >= wall.rect.x + wall.rect.w - 1, 'the board sits on the Meeting-2 east face');

  const hotspot = officeMap.hotspots.find((entry) => entry.kind === 'board');
  assert.equal(hotspot?.id, 'hs-board');
  assert.equal(hotspot?.zone, 'desk-collection');
});

void test('there is no invented Meeting 2 screen (furniture or hotspot)', () => {
  assert.equal(officeMap.furniture.filter((item) => item.kind === 'screen').length, 0, 'no screen furniture at all');
  assert.equal(officeMap.hotspots.filter((entry) => entry.id === 'hs-screen-meeting-2').length, 0);
  assert.equal(officeMap.hotspots.filter((entry) => entry.kind === 'screen').length, 0);
});

void test('the certificate table has its own hotspot distinct from the board', () => {
  const certFurniture = officeMap.furniture.find((item) => item.id === 'F-PS-CERT-TABLE');
  assert.ok(certFurniture, 'the certificate table furniture exists');
  const cert = officeMap.hotspots.find((entry) => entry.kind === 'certificate-table');
  assert.equal(cert?.id, 'hs-cert-table');
  assert.equal(cert?.zone, certFurniture!.zone);
  assert.deepEqual(cert?.rect, certFurniture!.rect);
});

void test('the west lane stays solid-free and corrected side chairs remain non-solid outside the banks', () => {
  const wall = officeMap.walls.find((entry) => entry.id === 'w-m2-east')!;
  const wallFace = wall.rect.x + wall.rect.w;
  const bankLeft = Math.min(officeMap.furniture.find((item) => item.id === 'F-DC-BANK-TOP')!.rect.x, officeMap.furniture.find((item) => item.id === 'F-DC-BANK-BOTTOM')!.rect.x);
  const laneWidth = bankLeft - wallFace;
  assert.ok(laneWidth >= officeMap.actor.halfWidth * 2, `west lane ${laneWidth} must fit the ${officeMap.actor.halfWidth * 2}-wide actor`);

  const lane: Rect = { x: wallFace, y: worldY(244), w: laneWidth, h: worldY(501) - worldY(244) };
  for (const item of officeMap.furniture) {
    if (!item.solid) continue;
    assert.equal(intersectRect(lane, item.rect), null, `solid ${item.id} intrudes into the west lane`);
  }
  for (const id of ['F-DC-T-SIDE', 'F-DC-B-SIDE']) {
    const chair = officeMap.furniture.find((item) => item.id === id)!;
    assert.equal(chair.solid, false);
    assert.ok(chair.rect.x < bankLeft, `${id} sits left of the bank`);
    for (const deskId of ['F-DC-BANK-TOP', 'F-DC-BANK-BOTTOM']) {
      const desk = officeMap.furniture.find((item) => item.id === deskId)!;
      assert.equal(intersectRect(chair.rect, desk.rect), null, `${id} clears ${deskId}`);
    }
  }
});

