void test('actorFootBox models width and feet, anchored at the feet', () => {
  assert.deepEqual(actorFootBox(100, 200, { halfWidth: 9, feet: 12 }), { x: 91, y: 188, w: 18, h: 12 });
});

void test('walls, columns and solid furniture block movement', () => {
  const wall = officeMap.walls.find((entry) => entry.id === 'w-toprow-bottom')!;
  assert.equal(isBlocked(officeMap, wall.rect.x + 40, wall.rect.y + wall.rect.h / 2), true, 'full wall blocks');

  const column = officeMap.columns[0]!;
  assert.equal(isBlocked(officeMap, column.rect.x + column.rect.w / 2, column.rect.y + column.rect.h / 2), true, 'column blocks');

  const desk = officeMap.furniture.find((entry) => entry.solid && entry.kind === 'desk')!;
  assert.equal(isBlocked(officeMap, desk.rect.x + desk.rect.w / 2, desk.rect.y + desk.rect.h / 2), true, 'solid desk blocks');
});

void test('chair furniture is decorative and does not block', () => {
  const chair = officeMap.furniture.find((entry) => entry.kind === 'chair')!;
  assert.equal(chair.solid, false);
  assert.equal(isWalkable(officeMap, chair.rect.x + chair.rect.w / 2, chair.rect.y + chair.rect.h / 2), true);
});

void test('every door and gap opening is passable by the real actor', () => {
  for (const opening of officeMap.openings) {
    const horizontal = opening.orientation === 'horizontal';
    const cx = opening.rect.x + opening.rect.w / 2;
    const cy = opening.rect.y + opening.rect.h / 2;
    const candidates = horizontal
      ? [{ x: cx, y: cy }, { x: cx, y: cy - 8 }, { x: cx, y: cy + 8 }]
      : [{ x: cx, y: cy }, { x: cx - 8, y: cy }, { x: cx + 8, y: cy }];
    assert.ok(candidates.some((point) => isWalkable(officeMap, point.x, point.y)), `opening ${opening.id} is passable`);
  }
});

void test('the actor footprint blocks a body whose centre point would be clear', () => {
  const wall = officeMap.walls.find((entry) => entry.id === 'w-toprow-bottom')!;
  const x = 700;
  const y = wall.rect.y + wall.rect.h + 4;
  assert.equal(officeMap.walls.some((entry) => rectContainsPoint(entry.rect, x, y)), false, 'centre point is not inside a wall');
  assert.equal(isBlocked(officeMap, x, y), true, 'foot box still hits the wall');
  assert.equal(isBlocked(officeMap, x, y, { halfWidth: 0.1, feet: 0.1 }), false, 'a pin-point body fits');
});

void test('walkable spots across the map are reported as free', () => {
  const samples: Point[] = [
    { x: 300, y: 780 }, // lobby
    { x: 1542.5, y: 88.75 }, // Bilik Geng Kami, near seat 1
    { x: 1000, y: 260 }, // main circulation
    { x: 1100, y: 480 }, // Desk Collection, between the banks
    { x: 1650, y: 480 }, // Tele / CS / CA
  ];
  for (const point of samples) assert.equal(isWalkable(officeMap, point.x, point.y), true, `free at ${point.x},${point.y}`);
});

// ---------------------------------------------------------------------------
// Geometry primitives
// ---------------------------------------------------------------------------

void test('rectangle primitives behave as documented', () => {
  assert.equal(rectArea({ x: 0, y: 0, w: 10, h: 4 }), 40);
  assert.equal(rectContainsPoint({ x: 0, y: 0, w: 10, h: 10 }, 5, 5), true);
  assert.equal(rectContainsPoint({ x: 0, y: 0, w: 10, h: 10 }, 11, 5), false);
  assert.equal(rectContainsRect({ x: 0, y: 0, w: 10, h: 10 }, { x: 2, y: 2, w: 4, h: 4 }), true);
  assert.equal(rectContainsRect({ x: 0, y: 0, w: 10, h: 10 }, { x: 2, y: 2, w: 20, h: 4 }), false);
  assert.deepEqual(intersectRect({ x: 0, y: 0, w: 10, h: 10 }, { x: 5, y: 5, w: 10, h: 10 }), { x: 5, y: 5, w: 5, h: 5 });
  assert.equal(intersectRect({ x: 0, y: 0, w: 10, h: 10 }, { x: 10, y: 0, w: 10, h: 10 }), null, 'edge-touching rects do not overlap');
});

