void test('zoneAt resolves the containing zone, preferring the smallest match', () => {
  assert.equal(zoneAt(officeMap, 300, 780)?.id, 'lobby-besar');
  assert.equal(zoneAt(officeMap, 1542.5, 88.75)?.id, BILIK_GENG_ZONE_ID);
  assert.equal(zoneAt(officeMap, 1000, 260)?.id, 'lorong-utama');
  assert.equal(zoneAt(officeMap, 550, 430)?.id, 'pantry');
  assert.equal(zoneAt(officeMap, 1100, 480)?.id, 'desk-collection');
  assert.equal(zoneAt(officeMap, 0, 0), undefined);

  const layered = clone();
  layered.zones.push({ id: 'everywhere', name: 'Everywhere', kind: 'open', rect: { x: 0, y: 0, w: officeMap.width, h: officeMap.height } });
  assert.equal(zoneAt(layered, 300, 780)?.id, 'lobby-besar', 'the smaller zone wins');
});

void test('seatFor maps a character id to its assigned seat', () => {
  assert.equal(seatFor(officeMap, 1)?.id, 'seat-1');
  assert.equal(seatFor(officeMap, 6)?.id, 'seat-6');
  assert.equal(seatFor(officeMap, 99), undefined);
});

