void test('nearestHotspot finds hotspots by proximity and supports kind filters', () => {
  const seat = seatFor(officeMap, 1)!;
  const nearSeat = nearestHotspot(officeMap, seat.x, seat.y);
  assert.equal(nearSeat?.hotspot.id, 'hs-seat-1');
  assert.equal(nearSeat?.distance, 0);

  assert.equal(nearestHotspot(officeMap, 0, 0, { maxDistance: 40 }), null);

  const lift = officeMap.hotspots.find((hotspot) => hotspot.kind === 'lift')!;
  const found = nearestHotspot(officeMap, lift.rect.x + lift.rect.w / 2, lift.rect.y + lift.rect.h / 2, { kinds: ['lift'] });
  assert.equal(found?.hotspot.id, lift.id);

  const kinds: HotspotKind[] = ['exit'];
  const exit = officeMap.hotspots.find((hotspot) => hotspot.kind === 'exit')!;
  const exitFound = nearestHotspot(officeMap, exit.rect.x + exit.rect.w / 2, exit.rect.y + exit.rect.h / 2, { kinds });
  assert.equal(exitFound?.hotspot.action, 'status-pulang');
  assert.ok(DEFAULT_HOTSPOT_RANGE >= 40);
});

void test('the manifest carries the required data-driven hotspots', () => {
  const byKind = (kind: HotspotKind) => officeMap.hotspots.filter((hotspot) => hotspot.kind === kind);
  assert.equal(byKind('lift').length, 4, 'four lifts');
  assert.equal(byKind('seat').length, 6, 'six assigned chairs');
  assert.equal(byKind('gudang').length, 1, 'locked Gudang');
  assert.equal(byKind('fridge').length, 1, 'pantry fridge');
  assert.equal(byKind('dispenser').length, 4, 'pantry + HR/IT/Finance dispensers');
  assert.equal(byKind('board').length, 1, 'Best Agent board');
  assert.equal(byKind('certificate-table').length, 1, 'certificate table');
  assert.equal(byKind('server').length, 1, 'restricted server notice');
  assert.equal(byKind('reception').length, 1, 'reception info');
  assert.equal(byKind('exit').length, 1, 'single exit hotspot');
  assert.equal(byKind('screen').length, 0, 'no screens');

  for (const hotspot of officeMap.hotspots) {
    assert.ok(officeMap.zones.some((zone) => zone.id === hotspot.zone), `${hotspot.id} references a real zone`);
  }
});

