void test('clampCamera keeps the view inside the world for desktop and mobile', () => {
  const desktop = { w: 960, h: 540 };
  assert.deepEqual(clampCamera(officeMap, desktop, { x: 960, y: 480 }), { x: 480, y: 210 });
  assert.deepEqual(clampCamera(officeMap, desktop, { x: 0, y: 0 }), { x: 0, y: 0 });
  assert.deepEqual(clampCamera(officeMap, desktop, { x: 5000, y: 5000 }), { x: 960, y: 420 });

  const mobile = { w: 560, h: 360 };
  assert.deepEqual(clampCamera(officeMap, mobile, { x: 100, y: 100 }), { x: 0, y: 0 });
  assert.deepEqual(clampCamera(officeMap, mobile, { x: 1600, y: 800 }), { x: 1320, y: 600 });

  const oversized = { w: 2400, h: 1200 };
  assert.deepEqual(clampCamera(officeMap, oversized, { x: 960, y: 480 }), { x: 0, y: 0 }, 'a view larger than the world pins to the origin');
});

// ---------------------------------------------------------------------------
// Route reachability (grid BFS over the walkable space, real 18x12 actor)
// ---------------------------------------------------------------------------

const STEP = 6;

function reachableFrom(manifest: OfficeManifest, from: Point): Set<number> {
  const cols = Math.floor(manifest.width / STEP) + 1;
  const rows = Math.floor(manifest.height / STEP) + 1;
  const index = (i: number, j: number): number => j * cols + i;

  const start = index(Math.round(from.x / STEP), Math.round(from.y / STEP));
  assert.equal(isWalkable(manifest, from.x, from.y), true, `BFS origin ${from.x},${from.y} is walkable`);

  const seen = new Set<number>([start]);
  const queue: number[] = [start];
  for (let head = 0; head < queue.length; head += 1) {
    const i = queue[head]! % cols;
    const j = (queue[head]! - i) / cols;
    for (const [di, dj] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ] as const) {
      const ni = i + di;
      const nj = j + dj;
      if (ni < 0 || nj < 0 || ni >= cols || nj >= rows) continue;
      const key = index(ni, nj);
      if (seen.has(key)) continue;
      if (isBlocked(manifest, ni * STEP, nj * STEP)) continue;
      seen.add(key);
      queue.push(key);
    }
  }
  return seen;
}

function reaches(manifest: OfficeManifest, seen: Set<number>, point: Point): boolean {
  const cols = Math.floor(manifest.width / STEP) + 1;
  const rows = Math.floor(manifest.height / STEP) + 1;
  const ci = Math.round(point.x / STEP);
  const cj = Math.round(point.y / STEP);
  for (let di = -1; di <= 1; di += 1) {
    for (let dj = -1; dj <= 1; dj += 1) {
      const i = ci + di;
      const j = cj + dj;
      if (i < 0 || j < 0 || i >= cols || j >= rows) continue;
      if (seen.has(j * cols + i)) return true;
    }
  }
  return false;
}

void test('every required area is reachable from the lobby entrance with the real actor', () => {
  const seen = reachableFrom(officeMap, { x: 300, y: 780 });
  const goals: Array<[string, Point]> = [
    ['Reception', { x: 480, y: 300 }],
    ['Main circulation', { x: 1000, y: 260 }],
    ['Ruang Meeting 1', { x: 560, y: 120 }],
    ['Ruangan HRGA', { x: 775, y: 215 }],
    ['Bilik Komisaris', { x: 985, y: 210 }],
    ['Bilik Product Manager', { x: 1040, y: 210 }],
    ['Bilik IT', { x: 1180, y: 90 }],
    ['Bilik Direktur Finance', { x: 1330, y: 210 }],
    ['Pantry', { x: 560, y: 450 }],
    ['Wash path', { x: worldX(537), y: worldY(440) }],
    ['Wastafel', { x: 671, y: 600 }],
    ['Ruang Meeting 2', { x: 800, y: 320 }],
    ['Desk Collection (lower bank)', { x: 1100, y: 480 }],
    ['Tele / CS / CA', { x: 1650, y: 480 }],
    ['Server door approach', { x: 890, y: 550 }],
  ];
  for (const [name, point] of goals) {
    assert.equal(isWalkable(officeMap, point.x, point.y), true, `${name} goal is walkable`);
    assert.equal(reaches(officeMap, seen, point), true, `${name} is reachable from the lobby`);
  }
});

void test('the six assigned seats are reachable from the lobby entrance', () => {
  const seen = reachableFrom(officeMap, { x: 300, y: 780 });
  for (const seat of officeMap.seats) {
    assert.equal(reaches(officeMap, seen, { x: seat.x, y: seat.y }), true, `${seat.id} is reachable`);
  }
});

void test('every non-sealed zone has a reachable standable cell', () => {
  const seen = reachableFrom(officeMap, { x: 300, y: 780 });
  const cols = Math.floor(officeMap.width / STEP) + 1;
  const sealed = new Set(['gudang', 'toilet-wanita', 'toilet-pria', 'server']);
  for (const zone of officeMap.zones) {
    if (sealed.has(zone.id)) continue;
    let found = false;
    for (let x = zone.rect.x + STEP; x < zone.rect.x + zone.rect.w && !found; x += STEP) {
      for (let y = zone.rect.y + STEP; y < zone.rect.y + zone.rect.h && !found; y += STEP) {
        if (zoneAt(officeMap, x, y)?.id !== zone.id) continue;
        if (seen.has(Math.round(y / STEP) * cols + Math.round(x / STEP))) found = true;
      }
    }
    assert.equal(found, true, `${zone.id} has a reachable cell`);
  }
});
